// Decodes on first use and plays. Kept deliberately small: the game already has
// a master gain and a lazily created AudioContext, so this only needs to turn
// base64 into AudioBuffers and hand back BufferSources.
export function makeSamplePlayer(ac, dest, samples) {
  const bufs = {};
  let ready = false;

  function bytes(b64) {
    const bin = atob(b64);
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out.buffer;
  }

  // decodeAudioData is async and the first anvil blow can land before it
  // finishes. Callers check ready() and fall back to the synthesised voice, so
  // a slow decode is a slightly different sound for one blow, never silence.
  const load = Promise.all(Object.keys(samples).map(function (k) {
    return ac.decodeAudioData(bytes(samples[k]))
      .then(function (b) { bufs[k] = b; })
      .catch(function () { /* a codec that cannot read our mp3 leaves bufs[k] unset */ });
  })).then(function () { ready = true; });

  return {
    load: load,
    ready: function () { return ready; },
    has: function (n) { return !!bufs[n]; },

    // opt: gain, detune (cents), loop, when (seconds, defaults to now)
    play: function (name, opt) {
      opt = opt || {};
      const b = bufs[name];
      if (!b) return null;
      const src = ac.createBufferSource();
      src.buffer = b;
      src.loop = !!opt.loop;
      // detune is not universally supported on BufferSource, so fall back to
      // playbackRate, which is the same thing done by hand.
      if (opt.detune) {
        if (src.detune) src.detune.value = opt.detune;
        else src.playbackRate.value = Math.pow(2, opt.detune / 1200);
      }
      const g = ac.createGain();
      g.gain.value = opt.gain === undefined ? 1 : opt.gain;
      src.connect(g); g.connect(dest);
      src.start(opt.when || 0);
      return { src: src, gain: g };
    }
  };
}
